import{Client}from"#client/index.js";import{resolveVerifiedRemoteDevelopmentClient}from"#setup/verified-remote-client.js";import{toErrorMessage}from"#shared/errors.js";async function runRemotePrint(e){let{options:t}=await resolveVerifiedRemoteDevelopmentClient({headers:e.headers,serverUrl:e.serverUrl,signal:e.signal,workspaceRoot:e.workspaceRoot}),{delivery:n}=await new Client(t).sessions.create({message:e.prompt,signal:e.signal}),r;try{r=await n.result({signal:e.signal})}catch(t){throw e.signal.aborted?Error(`Interrupted while reading session ${n.sessionId}; it may still be running.`):Error(`Session ${n.sessionId}: ${toErrorMessage(t)}`)}if(e.signal.aborted)throw Error(`Interrupted while reading session ${n.sessionId}; it may still be running.`);if(r.status===`failed`)throw Error(`Session ${n.sessionId} failed: ${r.error.message}`);if(r.status===`cancelled`)throw Error(`Turn in session ${n.sessionId} was cancelled.`);if(r.status===`awaiting-input`){let e=r.interactions.length>0&&r.interactions.every(e=>e.request.kind===`sign-in`);throw Error(e?`Session ${n.sessionId} is waiting for authorization; use the client API to follow it, or start a new conversation with eve remote connect.`:`Session ${n.sessionId} is waiting for input; use the client API to answer it, or start a new conversation with eve remote connect.`)}return r.reply??``}export{runRemotePrint};